import assert from 'node:assert/strict';
import { writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const root = '/workspace/scratch/ce74d2c3df38/Experiment-3';
const load = path => import(pathToFileURL(`${root}/${path}`).href);
const { Track } = await load('src/simulation/track.ts');
const { DEFAULT_SETUP, controls } = await load('src/simulation/config.ts');
const { GP_R1, GP_R2, SBK_1000 } = await load('src/simulation/bike-definitions.ts');
const { MX_250, MX_450, SM_450 } = await load('src/simulation/offroad/dirt-bikes.ts');
const { BikeVehicle } = await load('src/simulation/bike-vehicle.ts');
const { DirtBikeVehicle } = await load('src/simulation/offroad/dirt-bike-vehicle.ts');
const { createEntrant } = await load('src/simulation/offroad/session.ts');
const { rigTrack } = await load('src/simulation/offroad/jump-rig.ts');
const road = new Track('clear');
const dirt = rigTrack('valley-ridge-mx');
const cases = [];
for (const definition of [GP_R1, GP_R2, SBK_1000, MX_250, MX_450, SM_450]) {
  const offroad = !!definition.bike.offroad;
  const samples = {};
  for (const [name, frontTemp, rearTemp] of [
    ['cold', 40, 40], ['normal', 800, 800], ['frontHot', 1400, 40],
    ['rearHot', 40, 1400], ['bothHot', 1400, 1400], ['lowerHeat', 550, 550],
  ]) {
    const bike = createEntrant(0, 'medium', DEFAULT_SETUP, 'raw', definition);
    const track = offroad ? dirt : road;
    assert.equal(bike instanceof DirtBikeVehicle, offroad);
    assert.equal(bike instanceof BikeVehicle, true);
    bike.place(track, 45);
    bike.dynamics.speed = 28;
    bike.gear = 2;
    Object.assign(bike.input, { ...controls(), brake: 0.1, clutch: 0.1 });
    for (let i = 0; i < bike.tires.length; i++) bike.tires[i].discTemp = i < 2 ? frontTemp : rearTemp;
    bike.step(1 / 240, track);
    assert.equal(bike.riding, true);
    assert.equal(bike.dynamics.assists.abs, false);
    assert.ok(bike.dynamics.frontBrakeForce > 10);
    assert.ok(bike.dynamics.rearBrakeForce > 10);
    samples[name] = {
      initialFrontDiscCelsius: frontTemp, initialRearDiscCelsius: rearTemp,
      frontBrakeForce: bike.dynamics.frontBrakeForce,
      rearBrakeForce: bike.dynamics.rearBrakeForce,
      speedAfterStep: bike.speed,
    };
  }
  const gp = definition.id === 'gpr1' || definition.id === 'gpr2';
  const ratios = {};
  for (const [name, sample] of Object.entries(samples)) {
    const front = sample.frontBrakeForce / samples.cold.frontBrakeForce;
    const rear = sample.rearBrakeForce / samples.cold.rearBrakeForce;
    const expectFront = gp && ['frontHot', 'bothHot'].includes(name) ? 0.78 : 1;
    const expectRear = gp && ['rearHot', 'bothHot'].includes(name) ? 0.78 : 1;
    assert.ok(Math.abs(front - expectFront) < 1e-12, `${definition.id} ${name} front ${front}`);
    assert.ok(Math.abs(rear - expectRear) < 1e-12, `${definition.id} ${name} rear ${rear}`);
    ratios[name] = { front, rear };
  }
  cases.push({ vehicle: definition.id, adapter: offroad ? 'DirtBikeVehicle' : 'BikeVehicle', samples, ratios });
}
const report = {
  passed: true,
  scope: 'Production createEntrant, adapter step and actual dynamics front/rear brake forces; no private solver or brake argument interception.',
  fixture: 'Fresh independent physical states at 45 m, speed 28 m/s, Raw assists, front input 0.1 and rear input 0.1, one 1/240 s production step. Disc temperature is the only changed state between variants.',
  limits: 'This verifies the fade binding and vehicle eligibility. The assigned initial disc temperatures are controlled fixtures, not a natural heat-up/cool-down cycle or measured real brake temperatures.',
  cases,
};
writeFileSync(new URL('./brake-binding-probe.json', import.meta.url), JSON.stringify(report, null, 2) + '\n');
console.log(JSON.stringify({ passed: true, vehicles: cases.length, physicalStates: cases.length * 6, hotGain: 0.78, unaffectedVehicles: cases.filter(c => c.adapter === 'DirtBikeVehicle' || c.vehicle === 'sbk1000').map(c => c.vehicle) }));
